import type { AttributeChart, Lot } from './dataset.ts';
export interface AttributeModel {
  center: number;
  defectiveRate: number;
}
export interface AttributeRow {
  number: number;
  inspected: number;
  value: number;
  lcl: number;
  ucl: number;
  z: number;
  status: 'high' | 'low' | 'ok';
}
export function attributeModel(
  chart: AttributeChart,
  points: number[],
  lots: Lot[],
): AttributeModel {
  let d = 0;
  let c = 0;
  let n = 0;
  for (const number of points) {
    const lot = lots[number - 1];
    d += lot.defectives;
    c += lot.defects;
    n += lot.inspected;
  }
  return {
    center:
      chart === 'p'
        ? d / n
        : chart === 'np'
          ? d / points.length
          : chart === 'c'
            ? c / points.length
            : c / n,
    defectiveRate: d / n,
  };
}
export function attributeLot(chart: AttributeChart, model: AttributeModel, lot: Lot): AttributeRow {
  const center = model.center;
  const value =
    chart === 'p'
      ? lot.defectives / lot.inspected
      : chart === 'np'
        ? lot.defectives
        : chart === 'c'
          ? lot.defects
          : lot.defects / lot.inspected;
  const sigma = Math.sqrt(
    chart === 'p'
      ? (center * (1 - center)) / lot.inspected
      : chart === 'np'
        ? center * (1 - model.defectiveRate)
        : chart === 'c'
          ? center
          : center / lot.inspected,
  );
  const lcl = Math.max(0, center - 3 * sigma);
  const ucl = center + 3 * sigma;
  return {
    number: lot.number,
    inspected: lot.inspected,
    value,
    lcl,
    ucl,
    z: (value - center) / sigma,
    status: value > ucl ? 'high' : value < lcl ? 'low' : 'ok',
  };
}

import type { Constants, Sample, Spec } from './dataset.ts';
import type { Group } from './variable_charts.ts';
export function computeCapability(
  groups: Group[],
  samples: Sample[],
  spec: Spec,
  constants: Constants,
) {
  let total = 0;
  let ranges = 0;
  let deviations = 0;
  for (const sample of samples) total += sample.value;
  for (const group of groups) {
    ranges += group.range;
    deviations += group.sd;
  }
  const count = samples.length;
  const mean = total / count;
  const sigmaWithin = ranges / groups.length / constants.d2;
  const sigmaSbar = deviations / groups.length / constants.c4;
  let squares = 0;
  for (const sample of samples) {
    const difference = sample.value - mean;
    squares += difference * difference;
  }
  const sigmaOverall = Math.sqrt(squares / (count - 1));
  const cp = (spec.usl - spec.lsl) / (6 * sigmaWithin);
  const cpu = (spec.usl - mean) / (3 * sigmaWithin);
  const cpl = (mean - spec.lsl) / (3 * sigmaWithin);
  const cpk = Math.min(cpu, cpl);
  const pp = (spec.usl - spec.lsl) / (6 * sigmaOverall);
  const ppu = (spec.usl - mean) / (3 * sigmaOverall);
  const ppl = (mean - spec.lsl) / (3 * sigmaOverall);
  const ppk = Math.min(ppu, ppl);
  const offset = mean - spec.target;
  const cpm =
    (spec.usl - spec.lsl) / (6 * Math.sqrt(sigmaOverall * sigmaOverall + offset * offset));
  const interval = (value: number) => {
    const delta = spec.ci_z * Math.sqrt(1 / (9 * count) + (value * value) / (2 * (count - 1)));
    return [value - delta, value + delta];
  };
  const outOfSpec: (Sample & { side: 'low' | 'high' })[] = [];
  let below = 0;
  let above = 0;
  for (const sample of samples) {
    if (sample.value < spec.lsl) {
      below++;
      outOfSpec.push({ ...sample, side: 'low' });
    } else if (sample.value > spec.usl) {
      above++;
      outOfSpec.push({ ...sample, side: 'high' });
    }
  }
  return {
    mean,
    sigmaWithin,
    sigmaSbar,
    sigmaOverall,
    cp,
    cpu,
    cpl,
    cpk,
    pp,
    ppu,
    ppl,
    ppk,
    cpm,
    cpkCI: interval(cpk),
    ppkCI: interval(ppk),
    below,
    above,
    ppm: (1000000 * (below + above)) / count,
    verdict: cpk >= 1.33 ? 'capable' : cpk >= 1 ? 'marginal' : 'incapable',
    outOfSpec,
  };
}
export function frequencyDistribution(samples: Sample[], spec: Spec) {
  const width = spec.histogram_bin;
  let minimum = spec.lsl;
  let maximum = spec.usl;
  for (const sample of samples) {
    minimum = Math.min(minimum, sample.value);
    maximum = Math.max(maximum, sample.value);
  }
  const low = width * Math.floor(minimum / width);
  const high = width * Math.floor(maximum / width) + width;
  const frequencies: number[] = Array((high - low) / width).fill(0);
  for (const sample of samples) frequencies[Math.floor((sample.value - low) / width)]++;
  const top = Math.max(...frequencies);
  return frequencies.map((frequency, i) => {
    const lower = low + i * width;
    const upper = lower + width - 1;
    const marks: string[] = [];
    for (const [mark, value] of [
      ['lsl', spec.lsl],
      ['target', spec.target],
      ['usl', spec.usl],
    ] satisfies [string, number][]) {
      if (lower <= value && value <= upper) marks.push(mark);
    }
    return {
      lower,
      upper,
      frequency,
      marks,
      barLength: Math.floor((50 * frequency + top - 1) / top),
    };
  });
}

import { readFileSync } from 'node:fs';

export type Family = 'XBAR_R' | 'XBAR_S' | 'I_MR';
export type Shewhart = 'XBAR_R' | 'R' | 'XBAR_S' | 'S' | 'I' | 'MR';
export type Chart = Shewhart | 'CUSUM' | 'EWMA' | 'MA';
export type AttributeChart = 'p' | 'np' | 'c' | 'u';
export interface Spec {
  characteristic: string;
  lsl: number;
  usl: number;
  target: number;
  subgroup_size: number;
  phase1_subgroups: number;
  max_passes: number;
  rules: Record<Shewhart | 'STD', number[]>;
  cusum_k: number;
  cusum_h: number;
  ewma_lambda: number;
  ewma_l: number;
  ma_span: number;
  event_gap: number;
  ci_z: number;
  histogram_bin: number;
  rolling_window: number;
  rolling_step: number;
}
export interface Sample {
  number: number;
  subgroup: number;
  value: number;
}
export interface Lot {
  number: number;
  inspected: number;
  defectives: number;
  defects: number;
}
export interface Constants {
  A2: number;
  A3: number;
  B3: number;
  B4: number;
  D3: number;
  D4: number;
  d2: number;
  c4: number;
}
export const CONSTANTS: Record<number, Constants> = {
  2: { A2: 1.88, A3: 2.659, B3: 0, B4: 3.267, D3: 0, D4: 3.267, d2: 1.128, c4: 0.7979 },
