  5: { A2: 0.577, A3: 1.427, B3: 0, B4: 2.089, D3: 0, D4: 2.114, d2: 2.326, c4: 0.94 },
  6: { A2: 0.483, A3: 1.287, B3: 0.03, B4: 1.97, D3: 0, D4: 2.004, d2: 2.534, c4: 0.9515 },
  7: { A2: 0.419, A3: 1.182, B3: 0.118, B4: 1.882, D3: 0.076, D4: 1.924, d2: 2.704, c4: 0.9594 },
  8: { A2: 0.373, A3: 1.099, B3: 0.185, B4: 1.815, D3: 0.136, D4: 1.864, d2: 2.847, c4: 0.965 },
  9: { A2: 0.337, A3: 1.032, B3: 0.239, B4: 1.761, D3: 0.184, D4: 1.816, d2: 2.97, c4: 0.9693 },
  10: { A2: 0.308, A3: 0.975, B3: 0.284, B4: 1.716, D3: 0.223, D4: 1.777, d2: 3.078, c4: 0.9727 },
};
function lines(path: string): string[] {
  return readFileSync(path, 'ascii').trimEnd().split('\n');
}
export function readDataset() {
  const settings = lines('input/spec.txt').map((line) => line.split(' '));
  const number = (name: string) => Number(settings.find((row) => row[0] === name)![1]);
  const rules = (name: string) =>
    settings
      .find((row) => row[0] === 'rules' && row[1] === name)!
      .slice(2)
      .map(Number);
  const spec: Spec = {
    characteristic: settings[0][1],
    lsl: number('lsl'),
    usl: number('usl'),
    target: number('target'),
    subgroup_size: number('subgroup_size'),
    phase1_subgroups: number('phase1_subgroups'),
    max_passes: number('max_passes'),
    rules: {
      XBAR_R: rules('XBAR_R'),
      R: rules('R'),
      XBAR_S: rules('XBAR_S'),
      S: rules('S'),
      I: rules('I'),
      MR: rules('MR'),
      STD: rules('STD'),
    },
    cusum_k: number('cusum_k'),
    cusum_h: number('cusum_h'),
    ewma_lambda: number('ewma_lambda'),
    ewma_l: number('ewma_l'),
    ma_span: number('ma_span'),
    event_gap: number('event_gap'),
    ci_z: number('ci_z'),
    histogram_bin: number('histogram_bin'),
    rolling_window: number('rolling_window'),
    rolling_step: number('rolling_step'),
  };
  const samples: Sample[] = lines('input/measurements.csv')
    .slice(1)
    .map((line) => {
      const [number, subgroup, value] = line.split(',').map(Number);
      return { number, subgroup, value };
    });
  const lots: Lot[] = lines('input/attributes.csv')
    .slice(1)
    .map((line) => {
      const [number, inspected, defectives, defects] = line.split(',').map(Number);
      return { number, inspected, defectives, defects };
    });
  return { spec, samples, lots, constants: CONSTANTS[spec.subgroup_size] };
}

import { mkdirSync, writeFileSync } from 'node:fs';
import {
  readDataset,
  type Family,
  type Shewhart,
  type Chart,
  type AttributeChart,
  type Spec,
  type Lot,
} from './dataset.ts';
import {
  subgroupStatistics,
  movingRanges,
  familyLimits,
  outside,
  type Model,
  type Control,
  type Group,
} from './variable_charts.ts';
import { attributeModel, attributeLot, type AttributeRow } from './attribute_charts.ts';
import { runRules, zoneName, type RuleSignal } from './run_rules.ts';
import { computeCapability, frequencyDistribution } from './capability.ts';
import { variableBand, cusumBand, averageBand, standardizedBand } from './plot.ts';

const families: Family[] = ['XBAR_R', 'XBAR_S', 'I_MR'];
const charts: Chart[] = ['XBAR_R', 'R', 'XBAR_S', 'S', 'I', 'MR', 'CUSUM', 'EWMA', 'MA'];
const attributeCharts: AttributeChart[] = ['p', 'np', 'c', 'u'];
const familyCharts: Record<Family, [Shewhart, Shewhart]> = {
  XBAR_R: ['XBAR_R', 'R'],
  XBAR_S: ['XBAR_S', 'S'],
  I_MR: ['I', 'MR'],
};
type Data = ReturnType<typeof readDataset> & { groups: Group[] };
interface Pass {
  pass: number;
  count: number;
  model: Model;
  out: number[];
}
interface Estimation {
  retained: number[];
  removed: number[];
  passes: Pass[];
  status: string;
  model: Model;
}
interface Signal extends RuleSignal {
  chart: Chart;
  subgroup: number;
}
interface AverageRow {
  plus: number;
  minus: number;
  ewma: number;
  ewmaWidth: number;
  ma: number;
  maWidth: number;
}
interface Baseline {
  center: number;
  sigma: number;
  reference: number;
  threshold: number;
  ewmaWidth: number;
  maWidth: number;
}
interface Event {
  number: number;
  start: number;
  end: number;
  length: number;
  signals: Signal[];
  counts: number[];
  onset: number;
  shift: number;
  spread: number;
  outOfSpec: number;
  type: string;
  detection: Map<Chart, number>;
}
interface AttributeResult {
  retained: number[];
  removed: number[];
  status: string;
  passes: { pass: number; count: number; center: number; out: number[] }[];
  rows: AttributeRow[];
  signals: RuleSignal[];
}
const numbers = (first: number, last: number) =>
  Array.from({ length: last - first + 1 }, (_, i) => first + i);
function real(value: number): string {
  if (Math.abs(value) >= 1e21) return `${BigInt(value)}.0000`;
  const text = value.toFixed(4);
  return text === '-0.0000' ? '0.0000' : text;
}
const numberList = (values: number[]) => (values.length ? values.join(' ') : 'none');
const controlText = (name: string, c: Control) =>
  `${name} lcl ${real(c.lcl)} cl ${real(c.cl)} ucl ${real(c.ucl)}`;
function modelText(family: Family, model: Model): string {
  return `${controlText(family === 'I_MR' ? 'I' : 'XBAR', model.limits[0])} ${controlText(family === 'I_MR' ? 'MR' : family === 'XBAR_R' ? 'R' : 'S', model.limits[1])}`;
}
function estimateFamily(family: Family, data: Data): Estimation {
  const { spec, groups, samples, constants } = data;
  const initial = numbers(1, spec.phase1_subgroups * (family === 'I_MR' ? spec.subgroup_size : 1));
  let retained = initial;
  let model = familyLimits(family, retained, groups, samples, spec.subgroup_size, constants);
  let status = 'stopped';
  const passes: Pass[] = [];
  for (let pass = 1; pass <= spec.max_passes; pass++) {
    if (pass > 1) {
      model = familyLimits(family, retained, groups, samples, spec.subgroup_size, constants);
    }
    const excluded = new Set<number>();
    for (let j = 0; j < 2; j++) {
      for (const point of model.sequences[j]) {
        if (outside(point.value, model.limits[j])) excluded.add(point.number);
      }
    }
    const out = retained.filter((number) => excluded.has(number));
    passes.push({ pass, count: retained.length, model, out });
    if (!out.length) {
      status = 'converged';
      break;
    }
    if (pass === spec.max_passes) break;
    retained = retained.filter((number) => !excluded.has(number));
  }
  return {
    retained,
    removed: initial.filter((number) => !retained.includes(number)),
    passes,
    status,
    model,
  };
}
function monitorAverages(data: Data, estimates: Map<Family, Estimation>) {
  const { spec, constants, groups } = data;
  const xr = estimates.get('XBAR_R')!.model.limits;
  const center = xr[0].cl;
  const sigma = xr[1].cl / constants.d2 / Math.sqrt(spec.subgroup_size);
  const reference = spec.cusum_k * sigma;
  const threshold = spec.cusum_h * sigma;
  const lambda = spec.ewma_lambda;
  const q = (1 - lambda) * (1 - lambda);
  const rho = lambda / (2 - lambda);
  const ewmaWidth = spec.ewma_l * sigma * Math.sqrt(rho);
  const maWidth = (3 * sigma) / Math.sqrt(spec.ma_span);
  const baseline: Baseline = { center, sigma, reference, threshold, ewmaWidth, maWidth };
  const rows = new Map<number, AverageRow>();
  const signals: Signal[] = [];
  let plus = 0;
  let minus = 0;
  let plusLength = 0;
  let minusLength = 0;
  let z = center;
  let factor = 1;
  function emit(chart: Chart, upper: boolean, start: number, end: number, value: number) {
    signals.push({
      chart,
      rule: upper ? 'UPPER' : 'LOWER',
      start,
      end,
      value,
      direction: upper ? 'UP' : 'DOWN',
      subgroup: end,
    });
  }
  for (const group of groups.slice(spec.phase1_subgroups)) {
    const end = group.number;
    plus = Math.max(0, plus + (group.mean - center - reference));
    minus = Math.max(0, minus + (center - group.mean - reference));
    plusLength = plus > 0 ? plusLength + 1 : 0;
    minusLength = minus > 0 ? minusLength + 1 : 0;
    const savedPlus = plus;
    const savedMinus = minus;
    if (plus > threshold) {
      emit('CUSUM', true, end - plusLength + 1, end, plus);
      plus = 0;
      plusLength = 0;
    }
    if (minus > threshold) {
      emit('CUSUM', false, end - minusLength + 1, end, minus);
      minus = 0;
      minusLength = 0;
    }
    z = lambda * group.mean + (1 - lambda) * z;
    factor = factor * q;
    const currentEwmaWidth = spec.ewma_l * sigma * Math.sqrt(rho * (1 - factor));
    if (z > center + currentEwmaWidth) emit('EWMA', true, end, end, z);
    if (z < center - currentEwmaWidth) emit('EWMA', false, end, end, z);
    const start = Math.max(spec.phase1_subgroups + 1, end - spec.ma_span + 1);
    const count = end - start + 1;
    let total = 0;
    for (let i = start; i <= end; i++) total += groups[i - 1].total;
    const ma = total / (spec.subgroup_size * count);
    const currentMaWidth = (3 * sigma) / Math.sqrt(count);
    if (ma > center + currentMaWidth) emit('MA', true, start, end, ma);
    if (ma < center - currentMaWidth) emit('MA', false, start, end, ma);
    rows.set(end, {
      plus: savedPlus,
      minus: savedMinus,
      ewma: z,
      ewmaWidth: currentEwmaWidth,
      ma,
      maWidth: currentMaWidth,
    });
  }
  return { baseline, rows, signals };
}
function characterizeEvents(
  signals: Signal[],
  data: Data,
  estimates: Map<Family, Estimation>,
  baseline: Baseline,
): Event[] {
  const ranges: { start: number; end: number }[] = [];
  for (const number of [...new Set(signals.map((s) => s.subgroup))].sort((a, b) => a - b)) {
    const previous = ranges.at(-1);
    if (previous && number - previous.end - 1 <= data.spec.event_gap) previous.end = number;
    else ranges.push({ start: number, end: number });
  }
  return ranges.map(({ start, end }, index) => {
    const found = signals.filter((s) => start <= s.subgroup && s.subgroup <= end);
    const counts = [0, 0, 0, 0, 0];
    const detection = new Map<Chart, number>();
    let onset: number | undefined;
    for (const s of found) {
      const spread = s.chart === 'R' || s.chart === 'S' || s.chart === 'MR';
      counts[
        s.direction === 'NONE'
          ? 4
          : spread
            ? s.direction === 'UP'
              ? 2
              : 3
            : s.direction === 'UP'
              ? 0
              : 1
      ]++;
      detection.set(s.chart, Math.min(detection.get(s.chart) ?? Infinity, s.subgroup));
      if (s.chart === 'CUSUM') onset = Math.min(onset ?? Infinity, s.start);
    }
    let best = 0;
    for (let i = 1; i < 5; i++) if (counts[i] > counts[best]) best = i;
    let total = 0;
    let deviations = 0;
    let outOfSpec = 0;
    for (let i = start; i <= end; i++) {
      const group = data.groups[i - 1];
      total += group.total;
      deviations += group.sd;
      for (const sample of group.samples) {
        if (sample.value < data.spec.lsl || sample.value > data.spec.usl) outOfSpec++;
      }
    }
    const length = end - start + 1;
    return {
      number: index + 1,
      start,
      end,
      length,
      signals: found,
      counts,
      detection,
      onset: onset ?? start,
      outOfSpec,
      type: ['SHIFT_UP', 'SHIFT_DOWN', 'SPREAD_UP', 'SPREAD_DOWN', 'PATTERN'][best],
      shift: (total / (data.spec.subgroup_size * length) - baseline.center) / baseline.sigma,
      spread: deviations / length / estimates.get('XBAR_S')!.model.limits[1].cl,
    };
  });
}
function estimateAttribute(chart: AttributeChart, lots: Lot[], spec: Spec): AttributeResult {
  const initial = numbers(1, lots.length);
  let retained = initial;
  let status = 'stopped';
  let model = attributeModel(chart, retained, lots);
  const passes: AttributeResult['passes'] = [];
  for (let pass = 1; pass <= spec.max_passes; pass++) {
    if (pass > 1) model = attributeModel(chart, retained, lots);
    const out = retained.filter(
      (number) => attributeLot(chart, model, lots[number - 1]).status !== 'ok',
    );
    passes.push({ pass, count: retained.length, center: model.center, out });
    if (!out.length) {
      status = 'converged';
      break;
    }
    if (pass === spec.max_passes) break;
    retained = retained.filter((number) => !out.includes(number));
  }
  const rows = lots.map((lot) => attributeLot(chart, model, lot));
  return {
    retained,
    removed: initial.filter((number) => !retained.includes(number)),
    status,
    passes,
    rows,
    signals: runRules(
      rows.map((row) => ({ number: row.number, value: row.z })),
      { lcl: -3, cl: 0, ucl: 3 },
      spec.rules.STD,
    ),
  };
}
function main() {
  const loaded = readDataset();
  const data: Data = {
    ...loaded,
    groups: subgroupStatistics(loaded.samples, loaded.spec.subgroup_size),
  };
  const { spec, groups, samples, constants } = data;
  const n = spec.subgroup_size;
  const m = spec.phase1_subgroups;
  const estimates = new Map<Family, Estimation>(families.map((f) => [f, estimateFamily(f, data)]));
  const checks = new Map<Shewhart, { control: Control; points: number; signals: RuleSignal[] }>();
  const signals: Signal[] = [];
  const phase2 = groups.slice(m);
  const means = phase2.map((g) => ({ number: g.number, value: g.mean }));
  const phaseSequences = {
    XBAR_R: means,
    R: phase2.map((g) => ({ number: g.number, value: g.range })),
    XBAR_S: means,
    S: phase2.map((g) => ({ number: g.number, value: g.sd })),
    I: samples.slice(m * n),
    MR: movingRanges(samples).filter((p) => p.number > m * n),
  };
  for (const family of families) {
    const model = estimates.get(family)!.model;
    familyCharts[family].forEach((chart, j) => {
      const sequence = model.sequences[j];
      const control = model.limits[j];
      checks.set(chart, {
        control,
        points: sequence.length,
        signals: runRules(sequence, control, spec.rules[chart]),
      });
      for (const signal of runRules(phaseSequences[chart], control, spec.rules[chart])) {
        signals.push({
          ...signal,
          chart,
          subgroup:
            chart === 'I' || chart === 'MR' ? Math.floor((signal.end - 1) / n) + 1 : signal.end,
        });
      }
    });
  }
  const averages = monitorAverages(data, estimates);
  const { baseline, rows } = averages;
  signals.push(...averages.signals);
  const ruleOrder = (r: RuleSignal['rule']) => (typeof r === 'number' ? r : r === 'UPPER' ? 9 : 10);
  signals.sort(
    (a, b) =>
      charts.indexOf(a.chart) - charts.indexOf(b.chart) ||
      a.end - b.end ||
      ruleOrder(a.rule) - ruleOrder(b.rule),
  );
  const events = characterizeEvents(signals, data, estimates, baseline);
  const eventAt = new Map<number, Event>();
  for (const event of events) for (let i = event.start; i <= event.end; i++) eventAt.set(i, event);
  const proposed = new Map<Family, { points: number[]; model: Model }>();
  for (const family of families) {
    const points = estimates.get(family)!.retained.slice();
    for (const group of phase2) {
      if (!eventAt.has(group.number)) {
        points.push(...(family === 'I_MR' ? group.samples.map((s) => s.number) : [group.number]));
      }
    }
    proposed.set(family, {
      points,
      model: familyLimits(family, points, groups, samples, n, constants),
    });
  }
  const attributes = new Map(
    attributeCharts.map((chart) => [chart, estimateAttribute(chart, data.lots, spec)]),
  );
  const limits = [
    `characteristic ${spec.characteristic}`,
    `subgroup_size ${n}`,
    `subgroups ${groups.length}`,
    `samples ${samples.length}`,
    `phase1_subgroups ${m}`,
  ];
  for (const family of families) {
    const result = estimates.get(family)!;
    limits.push(`family ${family}`);
    for (const p of result.passes) {
      limits.push(
        `pass ${p.pass} points ${p.count} ${modelText(family, p.model)} out ${numberList(p.out)}`,
      );
    }
    limits.push(
      `result ${result.status} passes ${result.passes.length} retained ${result.retained.length} removed ${numberList(result.removed)}`,
    );
  }
  for (const [chart, check] of checks) {
    for (const s of check.signals) {
      limits.push(`phase1_signal ${chart} ${s.rule} ${s.start} ${s.end} ${real(s.value)}`);
    }
    limits.push(`phase1_check ${chart} points ${check.points} signals ${check.signals.length}`);
  }
  for (const family of families) {
    const p = proposed.get(family)!;
    limits.push(`proposed ${family} points ${p.points.length} ${modelText(family, p.model)}`);
  }
  const { center, sigma, reference, threshold, ewmaWidth, maWidth } = baseline;
  limits.push(
    `cusum target ${real(center)} sigma ${real(sigma)} k ${real(reference)} h ${real(threshold)}`,
    `ewma target ${real(center)} sigma ${real(sigma)} lcl ${real(center - ewmaWidth)} ucl ${real(center + ewmaWidth)}`,
    `ma target ${real(center)} sigma ${real(sigma)} span ${spec.ma_span} lcl ${real(center - maWidth)} ucl ${real(center + maWidth)}`,
  );
  for (const chart of charts) {
    const found = signals.filter((s) => s.chart === chart);
    const ends = new Set(found.map((s) => s.end));
    const rules: RuleSignal['rule'][] =
      chart === 'CUSUM' || chart === 'EWMA' || chart === 'MA'
        ? ['UPPER', 'LOWER']
        : spec.rules[chart];
    const points = chart === 'I' || chart === 'MR' ? samples.length - m * n : groups.length - m;
    limits.push(
      `phase2 ${chart} points ${points} signals ${found.length} signalled ${ends.size} first ${found[0]?.end ?? 'none'} by_rule ${rules.map((r) => `${r}:${found.filter((s) => s.rule === r).length}`).join(' ')}`,
    );
  }
  const eventLines = [`events ${events.length}`];
  for (const e of events) {
    eventLines.push(
      `event ${e.number} start ${e.start} end ${e.end} length ${e.length} signals ${e.signals.length} charts ${charts.filter((c) => e.detection.has(c)).join(',')}` +
        ` location_up ${e.counts[0]} location_down ${e.counts[1]} spread_up ${e.counts[2]} spread_down ${e.counts[3]} pattern ${e.counts[4]} onset ${e.onset}` +
        ` shift ${real(e.shift)} spread ${real(e.spread)} out_of_spec ${e.outOfSpec} type ${e.type}`,
      `detection ${e.number} ${charts.map((c) => `${c}:${e.detection.get(c) ?? '-'}`).join(' ')}`,
    );
  }
  const subgroupLines = [
    'subgroup,phase,mean,zone,range,sd,cusum_upper,cusum_lower,ewma,ma,signals,event',
  ];
  const xr = estimates.get('XBAR_R')!;
  for (const g of groups) {
    const row = rows.get(g.number);
    const phase = g.number > m ? 'phase2' : xr.removed.includes(g.number) ? 'excluded' : 'phase1';
    subgroupLines.push(
      [
        g.number,
        phase,
        real(g.mean),
        zoneName(g.mean, xr.model.limits[0]),
        g.range,
        real(g.sd),
        ...(row ? [row.plus, row.minus, row.ewma, row.ma].map(real) : ['-', '-', '-', '-']),
        signals.filter((s) => s.subgroup === g.number).length,
        eventAt.get(g.number)?.number ?? '-',
      ].join(','),
    );
  }
  const attributeLines: string[] = [];
  for (const chart of attributeCharts) {
    const r = attributes.get(chart)!;
    attributeLines.push(`chart ${chart}`);
    for (const p of r.passes) {
      attributeLines.push(
        `pass ${p.pass} lots ${p.count} center ${real(p.center)} out ${numberList(p.out)}`,
      );
    }
    attributeLines.push(
      `result ${r.status} passes ${r.passes.length} retained ${r.retained.length} removed ${numberList(r.removed)}`,
    );
    for (const row of r.rows) {
      attributeLines.push(
        `lot ${row.number} size ${row.inspected} value ${chart === 'np' || chart === 'c' ? row.value : real(row.value)} lcl ${real(row.lcl)} ucl ${real(row.ucl)} z ${real(row.z)} status ${row.status}`,
      );
    }
    for (const s of r.signals) {
      attributeLines.push(`signal ${s.rule} ${s.start} ${s.end} ${real(s.value)}`);
    }
    attributeLines.push(`signals ${r.signals.length}`);
  }
  const capabilityLines: string[] = [];
  function target(points: number[]) {
    const selected = points.map((i) => groups[i - 1]);
    const values = selected.flatMap((g) => g.samples);
    return { selected, values, result: computeCapability(selected, values, spec, constants) };
  }
  const fields = [
    ['mean', 'mean'],
    ['sigma_within', 'sigmaWithin'],
    ['sigma_sbar', 'sigmaSbar'],
    ['sigma_overall', 'sigmaOverall'],
    ['cp', 'cp'],
    ['cpu', 'cpu'],
    ['cpl', 'cpl'],
    ['cpk', 'cpk'],
    ['pp', 'pp'],
    ['ppu', 'ppu'],
    ['ppl', 'ppl'],
    ['ppk', 'ppk'],
    ['cpm', 'cpm'],
  ] satisfies [
    string,
    keyof Pick<
      ReturnType<typeof computeCapability>,
      | 'mean'
      | 'sigmaWithin'
      | 'sigmaSbar'
      | 'sigmaOverall'
      | 'cp'
      | 'cpu'
      | 'cpl'
      | 'cpk'
      | 'pp'
      | 'ppu'
      | 'ppl'
      | 'ppk'
      | 'cpm'
    >,
  ][];
  for (const [name, points] of [
    ['phase1', xr.retained],
    ['phase2', numbers(m + 1, groups.length)],
  ] satisfies [string, number[]][]) {
    const t = target(points);
    const v = t.result;
    capabilityLines.push(`group ${name} subgroups ${t.selected.length} values ${t.values.length}`);
    for (const [label, key] of fields) capabilityLines.push(`${label} ${real(v[key])}`);
    capabilityLines.push(
      `cpk_ci ${v.cpkCI.map(real).join(' ')}`,
      `ppk_ci ${v.ppkCI.map(real).join(' ')}`,
      `below_lsl ${v.below}`,
      `above_usl ${v.above}`,
      `ppm ${real(v.ppm)}`,
    );
    for (const s of v.outOfSpec) {
      capabilityLines.push(
        `out_of_spec sample ${s.number} subgroup ${s.subgroup} value ${s.value} side ${s.side}`,
      );
    }
    capabilityLines.push(`verdict ${v.verdict}`);
    for (const bin of frequencyDistribution(t.values, spec)) {
      capabilityLines.push(
        `bin ${bin.lower} ${bin.upper} ${bin.frequency}` +
          (bin.barLength ? ' ' + '#'.repeat(bin.barLength) : '') +
          (bin.marks.length ? ' ' + bin.marks.join(' ') : ''),
      );
    }
  }
  for (
    let start = m + 1;
    start + spec.rolling_window - 1 <= groups.length;
    start += spec.rolling_step
  ) {
    const end = start + spec.rolling_window - 1;
    const v = target(numbers(start, end)).result;
    capabilityLines.push(
      `rolling ${start} ${end} mean ${real(v.mean)} sigma_within ${real(v.sigmaWithin)} sigma_overall ${real(v.sigmaOverall)} cpk ${real(v.cpk)} ppk ${real(v.ppk)} verdict ${v.verdict}`,
    );
  }
  const chartLines: string[] = [];
  const has = (chart: Chart, end: number, rule?: RuleSignal['rule']) =>
    signals.some(
      (s) => s.chart === chart && s.end === end && (rule === undefined || s.rule === rule),
    );
  const pictures: {
    name: string;
    chart: Chart;
    family: Family;
    control: 0 | 1;
    property: 'mean' | 'range' | 'sd';
  }[] = [
    { name: 'XBAR', chart: 'XBAR_R', family: 'XBAR_R', control: 0, property: 'mean' },
    { name: 'R', chart: 'R', family: 'XBAR_R', control: 1, property: 'range' },
    { name: 'S', chart: 'S', family: 'XBAR_S', control: 1, property: 'sd' },
  ];
  const label = (number: number) => String(number).padStart(3, ' ');
  for (const p of pictures) {
    const f = estimates.get(p.family)!;
    const c = f.model.limits[p.control];
    chartLines.push(`chart ${controlText(p.name, c)}`);
    for (const g of groups) {
      chartLines.push(
        `${label(g.number)} ${g.number > m ? '2' : f.removed.includes(g.number) ? 'x' : '1'} ${variableBand(c, g[p.property], g.number > m && has(p.chart, g.number))} ${real(g[p.property])}`,
      );
    }
  }
  chartLines.push(`chart CUSUM h ${real(threshold)}`);
  for (const [i, r] of rows) {
    chartLines.push(
      `${label(i)} ${cusumBand(r.plus, r.minus, threshold, has('CUSUM', i, 'UPPER'), has('CUSUM', i, 'LOWER'))} ${real(r.plus)} ${real(r.minus)}`,
    );
  }
  for (const chart of ['EWMA', 'MA'] satisfies Chart[]) {
    const width = chart === 'EWMA' ? ewmaWidth : maWidth;
    chartLines.push(
      `chart ${controlText(chart, { lcl: center - width, cl: center, ucl: center + width })}`,
    );
    for (const [i, r] of rows) {
      const value = chart === 'EWMA' ? r.ewma : r.ma;
      const current = chart === 'EWMA' ? r.ewmaWidth : r.maWidth;
      chartLines.push(
        `${label(i)} ${averageBand(value, current, width, center, has(chart, i))} ${real(value)} ${real(center - current)} ${real(center + current)}`,
      );
    }
  }
  for (const chart of attributeCharts) {
    chartLines.push(`chart ${chart.toUpperCase()}_STD lcl -3.0000 cl 0.0000 ucl 3.0000`);
    for (const r of attributes.get(chart)!.rows) {
      chartLines.push(`${label(r.number)} ${standardizedBand(r.z, r.status)} ${real(r.z)}`);
    }
  }
  const reports: Record<string, string[]> = {
    'limits.txt': limits,
    'signals.csv': [
      'chart,rule,start,end,value,direction',
      ...signals.map(
        (s) => `${s.chart},${s.rule},${s.start},${s.end},${real(s.value)},${s.direction}`,
      ),
    ],
    'events.txt': eventLines,
    'subgroups.csv': subgroupLines,
    'attribute_charts.txt': attributeLines,
    'capability.txt': capabilityLines,
    'charts.txt': chartLines,
  };
  mkdirSync('output', { recursive: true });
  for (const [name, lines] of Object.entries(reports)) {
    writeFileSync(`output/${name}`, lines.join('\n') + '\n', 'ascii');
  }
}
main();

import type { Control } from './variable_charts.ts';
function place(band: string[], position: number, character: string) {
  band[Math.max(0, Math.min(60, position))] = character;
}
export function variableBand(c: Control, value: number, signal: boolean): string {
  const band: string[] = Array(61).fill('.');
  const position = (v: number) => Math.floor(60 * ((v - c.lcl) / (c.ucl - c.lcl)) + 0.5);
  place(band, 0, ':');
  place(band, 60, ':');
  place(band, position(c.cl), '|');
  place(band, position(value), signal ? '*' : 'o');
  return band.join('');
}
export function cusumBand(
  plus: number,
  minus: number,
  h: number,
  upper: boolean,
  lower: boolean,
): string {
  const band: string[] = Array(61).fill('.');
  place(band, 0, ':');
  place(band, 60, ':');
  place(band, 30, '|');
  if (minus > 0) {
    place(band, 30 - Math.min(30, Math.floor(30 * (minus / h) + 0.5)), lower ? '*' : '-');
  }
  if (plus > 0) {
    place(band, 30 + Math.min(30, Math.floor(30 * (plus / h) + 0.5)), upper ? '*' : '+');
  }
  return band.join('');
}
export function averageBand(
  value: number,
  width: number,
  full: number,
  center: number,
  signal: boolean,
): string {
  const band: string[] = Array(61).fill('.');
  const e = Math.min(30, Math.floor(30 * (width / full) + 0.5));
  place(band, 30, '|');
  place(band, 30 - e, ':');
  place(band, 30 + e, ':');
  place(band, 30 + Math.floor(30 * ((value - center) / full) + 0.5), signal ? '*' : 'o');
  return band.join('');
}
export function standardizedBand(value: number, status: string): string {
  const band: string[] = Array(61).fill('.');
  place(band, 0, ':');
  place(band, 60, ':');
  place(band, 30, '|');
  place(band, 30 + Math.floor(10 * value + 0.5), status === 'ok' ? 'o' : '*');
  return band.join('');
}

import type { Control, Point } from './variable_charts.ts';
export type Direction = 'UP' | 'DOWN' | 'NONE';
export interface RuleSignal {
  rule: number | 'UPPER' | 'LOWER';
  start: number;
  end: number;
  value: number;
  direction: Direction;
}
export function zoneBoundaries(c: Control) {
  const a = (c.ucl - c.cl) / 3;
  const b = (c.cl - c.lcl) / 3;
  return { u1: c.cl + a, u2: c.cl + 2 * a, l1: c.cl - b, l2: c.cl - 2 * b };
}
export function runRules(sequence: Point[], c: Control, rules: number[]): RuleSignal[] {
  const lengths = [0, 1, 3, 5, 8, 6, 14, 15, 8];
  const zones = zoneBoundaries(c);
  const signals: RuleSignal[] = [];
  for (let i = 0; i < sequence.length; i++) {
    for (const rule of rules) {
      const length = lengths[rule];
      if (i + 1 < length) continue;
      const window = sequence.slice(i - length + 1, i + 1);
      const values = window.map((p) => p.value);
      const last = sequence[i].value;
      let direction: Direction | undefined;
      if (rule === 1 && outside(last, c)) direction = last > c.cl ? 'UP' : 'DOWN';
      if (rule === 2 || rule === 3) {
        const upper = rule === 2 ? zones.u2 : zones.u1;
        const lower = rule === 2 ? zones.l2 : zones.l1;
        const required = rule === 2 ? 2 : 4;
        if (last > upper && values.filter((v) => v > upper).length >= required) direction = 'UP';
        else if (last < lower && values.filter((v) => v < lower).length >= required) {
          direction = 'DOWN';
        }
      }
      if (rule === 4) {
        if (values.every((v) => v > c.cl)) direction = 'UP';
        else if (values.every((v) => v < c.cl)) direction = 'DOWN';
      }
      if (rule === 5) {
        if (values.every((v, j) => j === 0 || v > values[j - 1])) direction = 'UP';
        else if (values.every((v, j) => j === 0 || v < values[j - 1])) direction = 'DOWN';
      }
      if (rule === 6) {
        let previous = 0;
        let alternating = true;
        for (let j = 1; j < values.length; j++) {
          const sign = Math.sign(values[j] - values[j - 1]);
          if (sign === 0 || sign === previous) alternating = false;
          previous = sign;
        }
        if (alternating) direction = 'NONE';
      }
      if (rule === 7 && values.every((v) => zones.l1 < v && v < zones.u1)) direction = 'NONE';
      if (
        rule === 8 &&
        values.every((v) => v > zones.u1 || v < zones.l1) &&
        values.some((v) => v > zones.u1) &&
        values.some((v) => v < zones.l1)
      ) {
        direction = 'NONE';
      }
      if (direction) {
        signals.push({
          rule,
          start: window[0].number,
          end: sequence[i].number,
          value: last,
          direction,
        });
      }
    }
  }
  return signals;
}
function outside(v: number, c: Control) {
  return v > c.ucl || v < c.lcl;
}
export function zoneName(v: number, c: Control): string {
  const z = zoneBoundaries(c);
  return v > c.ucl
    ? 'OUT+'
    : v < c.lcl
      ? 'OUT-'
      : v > z.u2
        ? 'A+'
        : v > z.u1
          ? 'B+'
          : v > c.cl
            ? 'C+'
            : v < z.l2
              ? 'A-'
              : v < z.l1
                ? 'B-'
                : v < c.cl
                  ? 'C-'
                  : 'C0';
}

import { CONSTANTS, type Constants, type Family, type Sample } from './dataset.ts';
export interface Point {
  number: number;
  value: number;
}
export interface Control {
  lcl: number;
  cl: number;
  ucl: number;
}
export interface Group {
  number: number;
  samples: Sample[];
  total: number;
  squares: number;
  mean: number;
  range: number;
  sd: number;
}
export interface Model {
  limits: [Control, Control];
  sequences: [Point[], Point[]];
}
export function subgroupStatistics(samples: Sample[], n: number): Group[] {
  const groups: Group[] = [];
  for (let start = 0; start < samples.length; start += n) {
    const members = samples.slice(start, start + n);
    let total = 0;
    let squares = 0;
    let low = members[0].value;
    let high = low;
    for (const { value } of members) {
      total += value;
      squares += value * value;
      low = Math.min(low, value);
      high = Math.max(high, value);
    }
    groups.push({
      number: members[0].subgroup,
      samples: members,
      total,
      squares,
      mean: total / n,
      range: high - low,
      sd: Math.sqrt((n * squares - total * total) / (n * (n - 1))),
    });
  }
  return groups;
}
export function movingRanges(points: Point[]): Point[] {
  return points
    .slice(1)
    .map((point, i) => ({ number: point.number, value: Math.abs(point.value - points[i].value) }));
}
export const outside = (value: number, control: Control) =>
  value < control.lcl || value > control.ucl;
export function familyLimits(
  family: Family,
  points: number[],
  groups: Group[],
  samples: Sample[],
  n: number,
  c: Constants,
): Model {
  if (family === 'I_MR') {
    const individual = points.map((number) => ({ number, value: samples[number - 1].value }));
    const ranges = movingRanges(individual);
    let total = 0;
    let spreadTotal = 0;
    for (const point of individual) total += point.value;
    for (const point of ranges) spreadTotal += point.value;
    const center = total / individual.length;
    const spread = spreadTotal / ranges.length;
    const two = CONSTANTS[2];
    const width = (3 * spread) / two.d2;
    return {
      limits: [
        { lcl: center - width, cl: center, ucl: center + width },
        { lcl: two.D3 * spread, cl: spread, ucl: two.D4 * spread },
      ],
      sequences: [individual, ranges],
    };
  }
  const selected = points.map((number) => groups[number - 1]);
  let total = 0;
  let spreadTotal = 0;
  for (const group of selected) {
    total += group.total;
    spreadTotal += family === 'XBAR_R' ? group.range : group.sd;
  }
  const center = total / (selected.length * n);
  const spread = spreadTotal / selected.length;
  const width = (family === 'XBAR_R' ? c.A2 : c.A3) * spread;
  return {
    limits: [
      { lcl: center - width, cl: center, ucl: center + width },
      {
        lcl: (family === 'XBAR_R' ? c.D3 : c.B3) * spread,
        cl: spread,
        ucl: (family === 'XBAR_R' ? c.D4 : c.B4) * spread,
      },
    ],
    sequences: [
      selected.map((g) => ({ number: g.number, value: g.mean })),
      selected.map((g) => ({ number: g.number, value: family === 'XBAR_R' ? g.range : g.sd })),
    ],
  };
}
